import json
d=json.load(open('/app/trial/agent/trajectory.json'))
steps=d['steps']
for i,s in enumerate(steps):
    tcs = s.get('tool_calls') or []
    for tc in tcs:
        name = tc.get('name') or tc.get('tool_name')
        args = tc.get('arguments') or tc.get('input') or {}
        if isinstance(args, dict):
            fp = args.get('file_path') or args.get('path')
        else:
            fp = None
        if name in ('Edit','Write') and fp and 'TextSVGExportMixin' in str(fp):
            print(i, name, fp)
"

